import math
def clamp(x,a,b): return max(a,min(b,x))
def nearest(p,line):
    best=None; bd=1e20
    for a,b in zip(line,line[1:]):
        dx=b[0]-a[0]; dy=b[1]-a[1]
        t=clamp(((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy+1e-9),0,1)
        q=(a[0]+t*dx,a[1]+t*dy)
        d=(p[0]-q[0])**2+(p[1]-q[1])**2
        if d<bd: bd=d; best=q
    return best,bd
def control(obs):
    m=obs['local_map']; left=m.get('left_rail',[]); right=m.get('right_rail',[])
    points=[]
    if len(left)>1 and len(right)>1:
        for rail,other in ((left,right),(right,left)):
            for p in rail:
                q,d=nearest(p,other)
                if q is not None and 8<d<28:
                    u=(p[0]+q[0])/2; v=(p[1]+q[1])/2
                    if u>0: points.append((u,v))
    if not points:
        return (0,0,180)
    target=min(points,key=lambda p:abs(math.hypot(*p)-3.8)+max(0,-p[0])*5)
    u,v=target
    curvature=2*v/max(2,u*u+v*v)
    desired=clamp(math.degrees(math.atan(2.9*curvature)),-36,36)
    h=obs['hitch_deg']
    steer=clamp(0.76*h+1.65*(h-desired),-34,34)
    speed=-0.85 if abs(desired)<12 else -0.65
    return (steer,speed,180)

