import math
def clip(x,a,b): return max(a,min(b,x))
def rail_at(pts,u):
    hits=[]
    for a,b in zip(pts,pts[1:]):
        if min(a[0],b[0])<=u<=max(a[0],b[0]) and abs(b[0]-a[0])>0.001:
            t=(u-a[0])/(b[0]-a[0]); hits.append(a[1]+t*(b[1]-a[1]))
    return min(hits,key=abs) if hits else None
def control(obs):
    m=obs.get('local_map',{})
    left=m.get('left_rail',[]); right=m.get('right_rail',[])
    target=None
    for u in [5.5,5,4.5,4,3,2]:
        l=rail_at(left,u); r=rail_at(right,u)
        if l is not None and r is not None:
            target=(u,(l+r)/2); break
    h=obs.get('hitch_deg',0)
    if target is None:
        return (clip(1.5*h,-40,40),0,180)
    u,v=target
    k=2*v/((u+1.4)**2+v*v)
    desired=clip(math.degrees(math.atan(4.9*k)),-36,36)
    a=math.radians(desired)
    ff=math.degrees(math.atan2(2.5*math.sin(a),3.6+1.3*math.cos(a)))
    steer=clip(ff+1.6*(h-desired),-45,45)
    speed=-0.85 if abs(h)<32 else -0.5
    return (steer,speed,180)

