import math

def clamp(x,a,b): return max(a,min(b,x))

def interp(points,x):
    p=sorted(points)
    for i in range(len(p)-1):
        a,b=p[i],p[i+1]
        if a[0]<=x<=b[0] and b[0]>a[0]:
            f=(x-a[0])/(b[0]-a[0]); return a[1]+f*(b[1]-a[1])
    return None

def control(obs):
    rails=obs.get('local_map',{})
    left=rails.get('left_rail',[]); right=rails.get('right_rail',[])
    centers=[]
    for x in range(0,25):
        a=interp(left,x); b=interp(right,x)
        if a is not None and b is not None: centers.append((x,(a+b)/2))
    h=obs.get('hitch_deg',0)
    if not centers:
        return (clamp(h*2,-35,35),0,180)
    aim=min(centers,key=lambda p:abs(p[0]-13))
    x,y=aim
    k=2*y/max(36,x*x+y*y)
    desired=math.degrees(math.asin(clamp(10.2*k,-0.65,0.65)))
    ff=math.degrees(math.atan(3.9/10.2*math.sin(math.radians(h))))
    steer=clamp(ff+1.9*(h-desired),-42,42)
    speed=-min(1.3, max(0.65,1.3-abs(h-desired)*0.025))
    if abs(h)>48:
        wake('Large hitch angle; braking for review')
        speed=0
    return (steer,speed,180)

